questionvariables.text:
/* Illustrative agricultural survey; values are randomised. */
idbase:(rand(80)+10)*10;
id1:idbase+1;
id2:idbase+2;
id3:idbase+3;
id4:idbase+4;

age1:rand(14)+21;
age2:rand(15)+35;
age3:rand(13)+27;
age4:rand(14)+45;
q_meanage:(age1+age2+age3+age4)/4;

/* Switch the displayed country pair between variants. */
region:rand(2);
country1:if region=0 then "Nigeria" else "Cameroon";
country2:if region=0 then "Cameroon" else "Nigeria";

/* The radio values are deliberately small integers.
   Display text is provided separately for each choice. */
tapredict:random_permutation([
 [1,true,"No. Farmer ID labels records; its mean has no useful interpretation."],
 [2,false,"Yes. Any column made of digits is a numerical measurement."],
 [3,false,"Yes, but only when the IDs are consecutive."],
 [4,false,"No, because R-Instat cannot store identifiers as numbers."]
]);

taage:random_permutation([
 [1,true,"Numeric"],[2,false,"Character"],
 [3,false,"Factor"],[4,false,"Ordered factor"]
]);
tacountry:random_permutation([
 [1,false,"Numeric"],[2,false,"Character"],
 [3,true,"Factor"],[4,false,"Ordered factor"]
]);
tanote:random_permutation([
 [1,false,"Numeric"],[2,true,"Character"],
 [3,false,"Factor"],[4,false,"Ordered factor"]
]);
tafreq:random_permutation([
 [1,false,"Numeric"],[2,false,"Character"],
 [3,false,"Factor without a specified order"],[4,true,"Ordered factor"]
]);
taidreason:random_permutation([
 [1,true,"The values are labels, not measurements; their average has no meaningful interpretation."],
 [2,false,"The IDs are too large for R-Instat to average."],
 [3,false,"An average is meaningful only when every ID is identical."],
 [4,false,"The average ID measures the average farmer age."]
]);
taidaction:random_permutation([
 [1,true,"Keep Farmer ID as an identifier and exclude it from numerical summaries."],
 [2,false,"Use the mean ID to describe the typical farmer."],
 [3,false,"Replace the IDs with ages so the column becomes numeric."],
 [4,false,"Delete the ID column because identifiers cannot be useful."]
]);
